const users = [
    { id: 1, name: 'John', isActive: true },
    { id: 2, name: 'Jane', isActive: false },
    { id: 3, name: 'Bob', isActive: true }
];

function calculateStats(users) {
    const activeUsersCount = users.filter(user => user.isActive).length;
    const inactiveUsersCount = users.length - activeUsersCount;
    const activePercentage = users.length > 0 
        ? ((activeUsersCount / users.length) * 100).toFixed(1) 
        : '0.0';
    return { activeUsersCount, inactiveUsersCount, activePercentage };
}

const stats = calculateStats(users);
console.log(stats);

if (stats.activeUsersCount !== 2) throw new Error('Active count wrong');
if (stats.inactiveUsersCount !== 1) throw new Error('Inactive count wrong');
if (stats.activePercentage !== '66.7') throw new Error('Percentage wrong: ' + stats.activePercentage);

console.log('Test passed');

